        if band == 'lower':
            def entry(i, j):
                if i == j:
                    return eigenvalue
                elif j + 1 == i:
                    return S.One
                return S.Zero
        else:
            def entry(i, j):
                if i == j:
                    return eigenvalue
                elif i + 1 == j:
                    return S.One
                return S.Zero
        return cls._new(rows, cols, entry)
    @classmethod
    def _eval_ones(cls, rows, cols):
        def entry(i, j):
            return S.One
        return cls._new(rows, cols, entry)
